(7053477, 1072578, 24073, '<td valign="top">WOW...good luck on the battle for first, there are a couple that will compete with you, but your chances are verry verry good.  Nice job, insanely great shot.</td>', 'WOW...good luck on the battle for first, there are a couple that will compete with you, but your chances are verry verry good.  Nice job, insanely great shot.', '2013-06-19 19:21:59.000000', NULL, 1),
(7053479, 1072520, 24073, '<td valign="top">Dude this was my 10 in the challenge, along with only one other, but I looked at it twice, and theres 8 people not seven.  So close, hope it doesn''t  hurt your chances too bad.  solid, solid 8.</td>', 'Dude this was my 10 in the challenge, along with only one other, but I looked at it twice, and theres 8 people not seven.  So close, hope it doesn''t  hurt your chances too bad.  solid, solid 8.', '2013-06-19 19:32:32.000000', NULL, 1),
